-- England and Wales historical knowledge base. Generated by scripts/build.py.
-- Signed historical years omit zero. Astronomical year = historical+1 for BCE.
-- SQLite 3.31+ is required for generated columns. Foreign keys must be enabled.
PRAGMA foreign_keys=ON;
-- Source catalogue: fetched URL or precise bibliography explicitly not fetched.
CREATE TABLE IF NOT EXISTS source (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, publisher TEXT NOT NULL, author TEXT,
 url TEXT, bibliographic_ref TEXT, access_status TEXT NOT NULL CHECK(access_status IN ('fetched','not_fetched')),
 checked_on TEXT NOT NULL, source_type TEXT NOT NULL, lead_only INTEGER NOT NULL DEFAULT 0 CHECK(lead_only IN (0,1)), notes TEXT,
 CHECK((access_status='fetched' AND url IS NOT NULL) OR (access_status='not_fetched' AND length(bibliographic_ref)>0))
);
-- Global entity registry allows referentially checked generic relations/citations.
CREATE TABLE IF NOT EXISTS entity (id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, packet TEXT NOT NULL);
-- Date evidence: earliest/latest bound the same uncertain instant, not a duration.
CREATE TABLE IF NOT EXISTS date_span (
 id TEXT PRIMARY KEY REFERENCES entity(id), earliest_year INTEGER NOT NULL CHECK(earliest_year<>0 AND earliest_year BETWEEN -4000 AND 1625),
 latest_year INTEGER NOT NULL CHECK(latest_year<>0 AND latest_year BETWEEN -4000 AND 1625 AND latest_year>=earliest_year),
 earliest_astronomical INTEGER GENERATED ALWAYS AS (CASE WHEN earliest_year<0 THEN earliest_year+1 ELSE earliest_year END) STORED,
 latest_astronomical INTEGER GENERATED ALWAYS AS (CASE WHEN latest_year<0 THEN latest_year+1 ELSE latest_year END) STORED,
 month INTEGER CHECK(month BETWEEN 1 AND 12), day INTEGER CHECK(day BETWEEN 1 AND 31),
 circa INTEGER NOT NULL CHECK(circa IN (0,1)), calendar TEXT NOT NULL, precision TEXT NOT NULL,
 qualifier TEXT NOT NULL DEFAULT 'at' CHECK(qualifier IN ('at','circa','between','by','before','after')), notes TEXT,
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 CHECK(day IS NULL OR month IS NOT NULL), CHECK(month IS NULL OR earliest_year=latest_year)
);

-- Named geographic entities; coordinates are anchors with an explicit error radius, never inferred boundaries.
CREATE TABLE IF NOT EXISTS place (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, kind TEXT NOT NULL, country TEXT NOT NULL CHECK(country IN ('england','wales','context')), lat REAL, lon REAL, uncertainty_m REAL, position_method TEXT NOT NULL CHECK(position_method IN ('surveyed','registered boundary centroid','gazetteer','inferred','unlocated')), position_source_id TEXT REFERENCES source(id), position_note TEXT, position_confidence TEXT CHECK(position_confidence IN ('high','medium','low')), CHECK((lat IS NULL AND lon IS NULL AND uncertainty_m IS NULL AND position_method='unlocated') OR (lat BETWEEN -90 AND 90 AND lon BETWEEN -180 AND 180 AND uncertainty_m>=0 AND position_method<>'unlocated' AND position_source_id IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS ix_place_source ON place(source_id);

-- Dated name attestations and languages. Dates describe attestation, not proof of exclusive use.
CREATE TABLE IF NOT EXISTS place_name (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 place_id TEXT NOT NULL REFERENCES place(id), name TEXT NOT NULL, language TEXT NOT NULL, name_type TEXT
);
CREATE INDEX IF NOT EXISTS ix_place_name_source ON place_name(source_id);

-- Dated states of a place; population and rank are separate explicitly based estimates.
CREATE TABLE IF NOT EXISTS place_phase (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 place_id TEXT NOT NULL REFERENCES place(id), phase_type TEXT NOT NULL, description TEXT NOT NULL, population_min REAL, population_max REAL, rank INTEGER, estimate_basis TEXT
);
CREATE INDEX IF NOT EXISTS ix_place_phase_source ON place_phase(source_id);

-- Named people; start/end mean birth/death bounds, not reigns.
CREATE TABLE IF NOT EXISTS person (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, role TEXT, description TEXT
);
CREATE INDEX IF NOT EXISTS ix_person_source ON person(source_id);

-- Institutional offices, including episcopal sees.
CREATE TABLE IF NOT EXISTS office (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, polity_id TEXT REFERENCES polity(id), place_id TEXT REFERENCES place(id), office_type TEXT
);
CREATE INDEX IF NOT EXISTS ix_office_source ON office(source_id);

-- A person holding an office; start/end are tenure bounds.
CREATE TABLE IF NOT EXISTS office_tenure (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 person_id TEXT NOT NULL REFERENCES person(id), office_id TEXT NOT NULL REFERENCES office(id), tenure_note TEXT
);
CREATE INDEX IF NOT EXISTS ix_office_tenure_source ON office_tenure(source_id);

-- Peoples, political units and administrative jurisdictions; no territorial polygon is implied.
CREATE TABLE IF NOT EXISTS polity (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, kind TEXT NOT NULL, description TEXT
);
CREATE INDEX IF NOT EXISTS ix_polity_source ON polity(source_id);

-- Dated phases of a polity, including creation and reorganisation.
CREATE TABLE IF NOT EXISTS polity_period (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 polity_id TEXT NOT NULL REFERENCES polity(id), description TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_polity_period_source ON polity_period(source_id);

-- Sourced reign claims, including overlapping or rival reigns.
CREATE TABLE IF NOT EXISTS ruler_of (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 person_id TEXT NOT NULL REFERENCES person(id), polity_id TEXT NOT NULL REFERENCES polity(id), title TEXT NOT NULL, tenure_note TEXT
);
CREATE INDEX IF NOT EXISTS ix_ruler_of_source ON ruler_of(source_id);

-- Dated events; start is the bounded occurrence, end is only supplied for an actual duration.
CREATE TABLE IF NOT EXISTS event (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, event_type TEXT NOT NULL, place_id TEXT REFERENCES place(id), description TEXT, outcome TEXT, consequences TEXT, campaign_id TEXT REFERENCES campaign(id)
);
CREATE INDEX IF NOT EXISTS ix_event_source ON event(source_id);

-- Battle detail linked to an event; site security is distinct from whether the battle happened.
CREATE TABLE IF NOT EXISTS battle (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 event_id TEXT NOT NULL REFERENCES event(id), site_security TEXT NOT NULL CHECK(site_security IN ('secure','approximate','disputed','unknown')), site_note TEXT, outcome TEXT, primary_sources TEXT
);
CREATE INDEX IF NOT EXISTS ix_battle_source ON battle(source_id);

-- One belligerent/commander assertion per row; sides are source-specific labels.
CREATE TABLE IF NOT EXISTS battle_party (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 event_id TEXT NOT NULL REFERENCES event(id), side TEXT NOT NULL, polity_id TEXT REFERENCES polity(id), commander_id TEXT REFERENCES person(id), description TEXT
);
CREATE INDEX IF NOT EXISTS ix_battle_party_source ON battle_party(source_id);

-- Source-specific numerical claims, not consensus totals; null is not zero.
CREATE TABLE IF NOT EXISTS battle_number (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 event_id TEXT NOT NULL REFERENCES event(id), side TEXT NOT NULL, quantity_type TEXT NOT NULL CHECK(quantity_type IN ('strength','casualties','killed','captured')), min_value REAL, max_value REAL, unit TEXT NOT NULL, number_basis TEXT NOT NULL, reliability TEXT NOT NULL CHECK(reliability IN ('high','medium','low','unknown')), CHECK(min_value IS NULL OR min_value>=0), CHECK(max_value IS NULL OR max_value>=min_value)
);
CREATE INDEX IF NOT EXISTS ix_battle_number_source ON battle_number(source_id);

-- Campaigns and movements, including epidemic spread; paths are not automatically known.
CREATE TABLE IF NOT EXISTS campaign (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, description TEXT, movement_type TEXT
);
CREATE INDEX IF NOT EXISTS ix_campaign_source ON campaign(source_id);

-- Ordered, dated stops. Connecting lines must not be treated as attested tracks.
CREATE TABLE IF NOT EXISTS waypoint (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 campaign_id TEXT NOT NULL REFERENCES campaign(id), sequence INTEGER NOT NULL, place_id TEXT REFERENCES place(id), event_id TEXT REFERENCES event(id), action TEXT NOT NULL, path_certainty TEXT NOT NULL CHECK(path_certainty IN ('attested_stop','inferred_link','unlocated')), interpolation_note TEXT, UNIQUE(campaign_id,sequence)
);
CREATE INDEX IF NOT EXISTS ix_waypoint_source ON waypoint(source_id);

-- Physical buildings or works linked to a place; construction details are separate phases.
CREATE TABLE IF NOT EXISTS structure (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, place_id TEXT NOT NULL REFERENCES place(id), structure_type TEXT NOT NULL, description TEXT
);
CREATE INDEX IF NOT EXISTS ix_structure_source ON structure(source_id);

-- Construction, alteration, use and destruction assertions; dimensions belong only to this phase.
CREATE TABLE IF NOT EXISTS structure_phase (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 structure_id TEXT NOT NULL REFERENCES structure(id), phase_type TEXT NOT NULL, description TEXT NOT NULL, material TEXT, length_m REAL, width_m REAL, height_m REAL, builder_id TEXT REFERENCES person(id), event_id TEXT REFERENCES event(id)
);
CREATE INDEX IF NOT EXISTS ix_structure_phase_source ON structure_phase(source_id);

-- Historical route identity, with explicit geometry status; ordered nodes are not a surveyed polyline.
CREATE TABLE IF NOT EXISTS route (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, route_type TEXT NOT NULL, description TEXT, geometry_status TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_route_source ON route(source_id);

-- Ordered source-supported route nodes.
CREATE TABLE IF NOT EXISTS route_node (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 route_id TEXT NOT NULL REFERENCES route(id), sequence INTEGER NOT NULL, place_id TEXT NOT NULL REFERENCES place(id), node_note TEXT, UNIQUE(route_id,sequence)
);
CREATE INDEX IF NOT EXISTS ix_route_node_source ON route_node(source_id);

-- Quantitative series definition and methodology; incompatible estimates stay separate.
CREATE TABLE IF NOT EXISTS timeline_series (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 name TEXT NOT NULL, measure TEXT NOT NULL, unit TEXT NOT NULL, geographic_scope TEXT NOT NULL, methodology TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_timeline_series_source ON timeline_series(source_id);

-- Dated quantitative observation/estimate; ranges are bounds, not statistical intervals unless stated.
CREATE TABLE IF NOT EXISTS timeline_value (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 series_id TEXT NOT NULL REFERENCES timeline_series(id), value_min REAL, value_max REAL, value_text TEXT, basis TEXT NOT NULL, place_id TEXT REFERENCES place(id), CHECK(value_min IS NULL OR value_max IS NULL OR value_max>=value_min)
);
CREATE INDEX IF NOT EXISTS ix_timeline_value_source ON timeline_value(source_id);

-- Explicit disagreement or interpretive uncertainty. Competing claim rows share dispute_id.
CREATE TABLE IF NOT EXISTS dispute (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 topic TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('unresolved','scholarly_disagreement','chronological_uncertainty','interpretive'))
);
CREATE INDEX IF NOT EXISTS ix_dispute_source ON dispute(source_id);

-- A source-specific assertion about any registered entity, including competing scholarly claims.
CREATE TABLE IF NOT EXISTS claim (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 subject_id TEXT NOT NULL REFERENCES entity(id), predicate TEXT NOT NULL, value_text TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_claim_source ON claim(source_id);

-- Typed directed link between any two entities; identity links do not erase conflicting claims.
CREATE TABLE IF NOT EXISTS relation (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 subject_id TEXT NOT NULL REFERENCES entity(id), predicate TEXT NOT NULL, object_id TEXT NOT NULL REFERENCES entity(id), description TEXT
);
CREATE INDEX IF NOT EXISTS ix_relation_source ON relation(source_id);

-- Comparison to a frozen JSON pointer; corrections, refinements and omissions are explicitly distinguished.
CREATE TABLE IF NOT EXISTS app_link (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 entity_id TEXT NOT NULL REFERENCES entity(id), app_file TEXT NOT NULL, app_id TEXT NOT NULL, json_pointer TEXT, comparison_type TEXT NOT NULL CHECK(comparison_type IN ('correction','uncertainty','refinement','omission','agreement')), app_claim TEXT NOT NULL, research_claim TEXT NOT NULL, importance INTEGER NOT NULL CHECK(importance BETWEEN 1 AND 5)
);
CREATE INDEX IF NOT EXISTS ix_app_link_source ON app_link(source_id);

-- Research leads, outstanding verification and coverage gaps; these are not established historical facts.
CREATE TABLE IF NOT EXISTS todo (
 id TEXT PRIMARY KEY REFERENCES entity(id),
 source_id TEXT NOT NULL REFERENCES source(id), checked_on TEXT NOT NULL,
 confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')),
 evidence_class TEXT NOT NULL CHECK(evidence_class IN ('attested-standing','attested-excavated','attested-documentary','attested-pictorial','reconstructed','conjectural','tradition')),
 notes TEXT, dispute_id TEXT REFERENCES dispute(id),
 start_date_id TEXT REFERENCES date_span(id), end_date_id TEXT REFERENCES date_span(id),
 topic TEXT NOT NULL, task TEXT NOT NULL, priority INTEGER NOT NULL CHECK(priority BETWEEN 1 AND 5), status TEXT NOT NULL CHECK(status IN ('open','blocked','done')), reason TEXT, lead_url TEXT, entity_id TEXT REFERENCES entity(id)
);
CREATE INDEX IF NOT EXISTS ix_todo_source ON todo(source_id);

-- Citation for any fact/date entity; locator and role identify the exact support.
CREATE TABLE IF NOT EXISTS citation (
 id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entity(id), source_id TEXT NOT NULL REFERENCES source(id),
 locator TEXT, citation_role TEXT NOT NULL, checked_on TEXT NOT NULL,
 UNIQUE(entity_id,source_id,citation_role)
);
CREATE INDEX IF NOT EXISTS ix_citation_entity ON citation(entity_id);
CREATE INDEX IF NOT EXISTS ix_event_type ON event(event_type);
CREATE INDEX IF NOT EXISTS ix_waypoint_campaign ON waypoint(campaign_id,sequence);
CREATE INDEX IF NOT EXISTS ix_place_location ON place(lat,lon);
CREATE INDEX IF NOT EXISTS ix_app_comparison ON app_link(comparison_type,importance);
-- Reproducibility ledger. Hashes are of the exact packet bytes loaded.
CREATE TABLE IF NOT EXISTS loaded_packet (path TEXT PRIMARY KEY, sha256 TEXT NOT NULL, record_count INTEGER NOT NULL);
-- App-friendly views keep date uncertainty and position quality visible.
CREATE VIEW IF NOT EXISTS event_timeline AS
 SELECT e.*,d.earliest_year,d.latest_year,d.earliest_astronomical,d.latest_astronomical,d.month,d.day,d.circa,d.calendar,d.qualifier,
 p.lat,p.lon,p.uncertainty_m,p.position_method FROM event e LEFT JOIN date_span d ON d.id=e.start_date_id LEFT JOIN place p ON p.id=e.place_id;
CREATE VIEW IF NOT EXISTS movement_timeline AS
 SELECT w.*,d.earliest_year,d.latest_year,d.month,d.day,d.circa,d.qualifier,p.name AS place_name,p.lat,p.lon,p.uncertainty_m,p.position_method
 FROM waypoint w LEFT JOIN date_span d ON d.id=w.start_date_id LEFT JOIN place p ON p.id=w.place_id;
CREATE VIEW IF NOT EXISTS app_disagreements AS
 SELECT a.*,s.title AS source_title,s.publisher,s.url,s.access_status FROM app_link a JOIN source s ON s.id=a.source_id
 WHERE a.comparison_type IN ('correction','uncertainty','refinement');
CREATE VIEW IF NOT EXISTS market_borough_by_1300 AS
 SELECT p.id AS place_id,p.name,p.country,p.lat,p.lon,p.uncertainty_m,ph.id AS assertion_id,ph.phase_type,
 d.earliest_year,d.latest_year,d.month,d.day,d.circa,d.qualifier,ph.source_id,ph.confidence,ph.evidence_class,
 CASE WHEN instr(COALESCE(ph.notes,''),'SOURCE QUALIFICATION PRESENT')>0 THEN 1 ELSE 0 END AS qualification_review_required
 FROM place p JOIN place_phase ph ON ph.place_id=p.id JOIN date_span d ON d.id=ph.start_date_id
 WHERE ph.source_id LIKE 'x-ihr-%' AND (ph.phase_type LIKE 'market_%' OR ph.phase_type='borough_attestation') AND d.latest_year<=1300;
CREATE VIEW IF NOT EXISTS place_timeline AS
 SELECT ph.*,p.name,p.lat,p.lon,p.uncertainty_m,p.position_method,d.earliest_year,d.latest_year,d.circa,d.qualifier
 FROM place_phase ph JOIN place p ON p.id=ph.place_id LEFT JOIN date_span d ON d.id=ph.start_date_id;

-- Unified provenance view across every typed fact and date row.
